def _win_is_admin() -> bool:
    try:
        import ctypes
        return bool(ctypes.windll.shell32.IsUserAnAdmin())
    except Exception:
        return False


def _win_open_target(target: str) -> dict:
    """Ouvre un fichier/URI/raccourci Windows : os.startfile (rapide, natif), avec repli
    `cmd /c start` si indisponible (ex. certains contextes de session)."""
    import subprocess as _sp
    try:
        os.startfile(target)
        return {"ok": True, "target": target}
    except Exception as e:
        try:
            flags = _sp.CREATE_NO_WINDOW if hasattr(_sp, "CREATE_NO_WINDOW") else 0
            r = _sp.run(["cmd.exe", "/c", "start", "", target], capture_output=True, timeout=15, creationflags=flags)
            return {"ok": r.returncode == 0, "target": target}
        except Exception as e2:
            return {"ok": False, "target": target, "error": f"{e} / repli: {e2}"}


async def execute_win_quick_launch_list(args: dict) -> dict:
    """Liste les raccourcis Windows disponibles (catalogue « Windows+ »), groupés."""
    admin_now = _win_is_admin()
    items = [{**o, "requires_admin": bool(o.get("admin", False))} for o in _WIN_SHORTCUTS]
    groups = {}
    for it in items:
        groups.setdefault(it["group"], []).append({"id": it["id"], "label": it["label"], "requires_admin": it["requires_admin"]})
    return {"success": True, "count": len(items), "groups": groups, "currently_admin": admin_now}


async def execute_win_quick_launch(args: dict) -> dict:
    """Ouvre directement un panneau/outil Windows (God Mode, ms-settings, panneaux legacy,
    outils admin .msc, dossiers utiles) par son id. Utiliser win_quick_launch_list pour voir
    les id disponibles. N'écrit/ne modifie rien (sauf God Mode : crée un dossier vide standard)."""
    action_id = (args.get("id") or args.get("action_id") or "").strip()
    if not action_id:
        return {"error": "Paramètre 'id' requis. Utilise win_quick_launch_list pour voir les options."}
    item = next((x for x in _WIN_SHORTCUTS if x["id"] == action_id), None)
    if not item:
        return {"error": f"Raccourci inconnu : {action_id!r}. Utilise win_quick_launch_list."}

    if item.get("kind") == "god_mode":
        desktop = Path(os.environ.get("USERPROFILE", str(Path.home()))) / "Desktop"
        god = desktop / "Marvin God Mode.{ED7BA470-8E54-465E-825C-99712043E01C}"
        god.mkdir(exist_ok=True)
        res = _win_open_target(str(god))
        return {"success": res["ok"], "path": str(god), "opened": res}

    if item.get("path_env") or item.get("path"):
        target = os.environ.get(item.get("path_env", ""), "") if item.get("path_env") else os.path.expandvars(item.get("path", ""))
        if not target:
            return {"error": "Chemin indisponible sur ce PC."}
        Path(target).mkdir(parents=True, exist_ok=True)
        res = _win_open_target(target)
        return {"success": res["ok"], "path": target, "opened": res}

    if item.get("uri"):
        res = _win_open_target(item["uri"])
        note = "Droits admin conseillés pour ce panneau." if item.get("admin") and not _win_is_admin() else None
        return {"success": res["ok"], "opened": res, "note": note}

    cmd = item.get("cmd") or []
    if not cmd:
        return {"error": "Raccourci mal configuré (aucune cible)."}
    target = cmd[0] if len(cmd) == 1 and cmd[0].lower().endswith((".msc", ".cpl", ".exe")) else None
    if target:
        res = _win_open_target(target)
    else:
        import subprocess as _sp
        flags = _sp.CREATE_NO_WINDOW if hasattr(_sp, "CREATE_NO_WINDOW") else 0
        try:
            r = _sp.run(cmd, capture_output=True, timeout=15, creationflags=flags)
            res = {"ok": r.returncode == 0, "target": " ".join(cmd)}
        except Exception as e:
            res = {"ok": False, "target": " ".join(cmd), "error": str(e)}
    return {"success": res["ok"], "opened": res}


async def execute_pc_system_info(args: dict) -> dict:
    try:
        mem = psutil.virtual_memory()
        cpu_pct = psutil.cpu_percent(interval=0.5)
        disks = []
        for dp in psutil.disk_partitions(all=False):
            try:
                usage = psutil.disk_usage(dp.mountpoint)
                disks.append({
                    "device": dp.device,
                    "mountpoint": dp.mountpoint,
                    "total_gb": round(usage.total / 1024**3, 1),
                    "used_gb": round(usage.used / 1024**3, 1),
                    "free_gb": round(usage.free / 1024**3, 1),
                    "percent": usage.percent,
                })
            except Exception:
                pass

        import platform
        uname = platform.uname()
        boot_time = psutil.boot_time()
        uptime_s = int(time.time() - boot_time)
        uptime_str = f"{uptime_s // 3600}h {(uptime_s % 3600) // 60}m"

        def fmt(n): return f"{n / 1024**3:.1f} Go"

        # Batterie (laptops uniquement)
        battery_info = None
        try:
            bat = psutil.sensors_battery()
            if bat is not None:
                battery_info = {
                    "percent": round(bat.percent, 1),
                    "plugged": bat.power_plugged,
                    "status": "En charge" if bat.power_plugged else "Sur batterie",
                }
                if bat.secsleft and bat.secsleft != psutil.POWER_TIME_UNLIMITED and bat.secsleft > 0:
                    h = bat.secsleft // 3600
                    m = (bat.secsleft % 3600) // 60
                    battery_info["time_left"] = f"{h}h {m}m"
        except Exception:
            pass

        # Réseau — interfaces actives
        net_ifaces = []
        try:
            addrs = psutil.net_if_addrs()
            stats = psutil.net_if_stats()
            for iface, addr_list in addrs.items():
                st = stats.get(iface)
                if st and st.isup:
                    ipv4 = next((a.address for a in addr_list if a.family.name == "AF_INET"), "")
                    if ipv4 and not ipv4.startswith("127."):
                        net_ifaces.append({"name": iface, "ip": ipv4, "speed_mbps": st.speed})
        except Exception:
            pass

        info = {
            "success": True,
            "platform": uname.system,
            "release": uname.release,
            "arch": uname.machine,
            "uptime": uptime_str,
            "cpu_percent": cpu_pct,
            "cpu_count_logical": psutil.cpu_count(logical=True),
            "cpu_count_physical": psutil.cpu_count(logical=False),
            "memory": {
                "total": fmt(mem.total),
                "used": fmt(mem.used),
                "free": fmt(mem.available),
                "percent": mem.percent,
            },
            "disks": disks,
            "network_interfaces": net_ifaces,
            "home": os.path.expanduser("~"),
        }
        if battery_info:
            info["battery"] = battery_info
        return info
    except Exception as e:
        return {"error": str(e)}


async def execute_pc_screenshot(args: dict) -> dict:
    # Accepte "path" (UI outils) ou "output_path" (agent)
    output_path = args.get("output_path") or args.get("path") or None
    embed = args.get("embed", False)  # True → retourner base64 au lieu de sauvegarder
    if output_path:
        output_path = _resolve_path(output_path)
    else:
        desktop = Path(os.path.expanduser("~")) / "Desktop"
        output_path = str(desktop / f"screenshot_{int(time.time())}.png")
    try:
        from PIL import ImageGrab
        import io, base64
        screenshot = ImageGrab.grab()
        if embed:
            buf = io.BytesIO()
            screenshot.save(buf, format="PNG")
            b64 = base64.b64encode(buf.getvalue()).decode("utf-8")
            return {
                "success": True,
                "message": "Capture d'écran prise",
                "image": f"data:image/png;base64,{b64}",
            }
        Path(output_path).parent.mkdir(parents=True, exist_ok=True)
        screenshot.save(output_path)
        return {"success": True, "message": f"Capture d'écran sauvegardée : {output_path}", "path": output_path}
    except Exception as e:
        return {"error": str(e)}


async def execute_pc_window_list(args: dict) -> dict:
    try:
        import win32gui
        windows = []

        def cb(hwnd, _):
            if win32gui.IsWindowVisible(hwnd):
                title = win32gui.GetWindowText(hwnd)
                if title and title.strip():
                    windows.append({"hwnd": hwnd, "title": title})

        win32gui.EnumWindows(cb, None)
        return {"success": True, "count": len(windows), "windows": windows}
    except ImportError:
        # Fallback: use tasklist
        result = await asyncio.to_thread(
            subprocess.run,
            "tasklist /FO CSV /NH", shell=True, capture_output=True, text=True, timeout=10
        )
        lines = [l.strip().strip('"') for l in result.stdout.splitlines() if l.strip()]
        windows = [{"title": l.split('","')[0]} for l in lines[:50]]
        return {"success": True, "count": len(windows), "windows": windows}
    except Exception as e:
        return {"error": str(e)}


async def execute_pc_window_focus(args: dict) -> dict:
    search = args.get("search", "")
    try:
        import win32gui
        import win32con

        target = None

        def cb(hwnd, _):
            nonlocal target
            if win32gui.IsWindowVisible(hwnd):
                title = win32gui.GetWindowText(hwnd)
                if search.lower() in title.lower():
                    target = (hwnd, title)

        win32gui.EnumWindows(cb, None)
        if target:
            hwnd, title = target
            win32gui.ShowWindow(hwnd, win32con.SW_RESTORE)
            win32gui.SetForegroundWindow(hwnd)
            return {"success": True, "message": f"Fenêtre mise au premier plan : {title}"}
        return {"error": f"Aucune fenêtre contenant « {search} » trouvée"}
    except Exception as e:
        return {"error": str(e)}


# ── v2.149 — Agent GUI local (lecture/clic/frappe via Windows UI Automation) ──────────
# Comble un vrai trou : Marvin avait déjà les "yeux" (pc_screenshot, screen_ocr,
# pc_window_list/focus) mais aucune "main" — aucun moyen de cliquer/taper dans une fenêtre.
# Choix délibéré : UI Automation (arbre structuré natif Windows) plutôt qu'un agent vision
# façon UI-TARS — 100% local, aucune capture d'écran envoyée à un modèle (donc aucun risque
# de fuite de données sensibles affichées à l'écran vers le cloud), et bien plus précis
# qu'un clic en coordonnées pixel qui casse au moindre pixel de décalage.
#
# Sécurité — pattern "lire un ID réel avant d'agir dessus" (même esprit que winget_install
# v2.113 et long_task_status v2.145) : pc_gui_click/pc_gui_type ne reçoivent JAMAIS de
# coordonnées figées d'une lecture précédente. Chaque appel refait une résolution LIVE de
# l'élément (par automation_id ou control_type+name+match_index) au moment même de l'action
# — protection structurelle contre une attaque TOCTOU (l'UI a changé entre la lecture et
# l'action : fenêtre fermée, élément déplacé, remplacé par autre chose). Si l'élément n'est
# plus là, l'appel échoue proprement plutôt que de cliquer au hasard.
#
# Le texte/les noms lus depuis l'UI (pc_gui_read) restent du CONTENU OBSERVÉ au sens de la
# règle de sécurité générale — jamais une instruction, même si un élément affiche un texte
# du style "clique ici". pc_gui_click/pc_gui_type sont dans DANGEROUS_TOOLS (confirmation
# obligatoire).
#
# Limite connue et assumée : UI Automation ne franchit pas la frontière UAC — une fenêtre
# élevée (admin) reste invisible/inaccessible depuis ce process non-admin. Pas de
# contournement ici (cliquer en tant qu'admin serait un risque d'un tout autre ordre que
# l'allowlist stricte du sidecar élevé, v2.90) — échec explicite si la fenêtre cible est
# élevée, à traiter au cas par cas si le besoin se présente vraiment.

_GUI_INTERACTIVE_TYPES = {
    "Button", "Edit", "Document", "ComboBox", "CheckBox", "RadioButton", "MenuItem", "MenuBar",
    "ListItem", "List", "TabItem", "Hyperlink", "Slider", "Spinner", "TreeItem",
    "SplitButton", "ToggleButton", "DataItem",
}


def _gui_get_window_sync(search: str):
    """Connecte à une fenêtre top-level via UI Automation. search vide → fenêtre au premier plan."""
    from pywinauto import Desktop
    import win32gui

    desktop = Desktop(backend="uia")
    if not search:
        hwnd = win32gui.GetForegroundWindow()
        if not hwnd:
            raise RuntimeError("Aucune fenêtre au premier plan.")
        title = win32gui.GetWindowText(hwnd)
        return desktop.window(handle=hwnd), title
    search_l = search.lower()
    for w in desktop.windows():
        try:
            title = w.window_text()
        except Exception:
            continue
        if title and search_l in title.lower():
            return w, title
    raise RuntimeError(f"Aucune fenêtre contenant « {search} » trouvée (ou fenêtre élevée/admin, inaccessible).")


# Types "porteurs de contenu" : leur `name` UIA EST le texte qu'ils contiennent (constaté en
# testant sur le Bloc-notes Windows 11 réel — control_type="Document", name="<tout le fichier>").
# Ce texte n'est PAS un identifiant stable (il change à chaque frappe) → jamais utilisé pour le
# matching de ré-résolution, seulement affiché (tronqué) à titre informatif. Le matching se fait
# par position (match_index) parmi les contrôles du même control_type dans la fenêtre.
_GUI_CONTENT_TYPES = {"Edit", "Document"}


def _gui_read_sync(search: str, max_elements: int) -> dict:
    window, title = _gui_get_window_sync(search)
    elements = []
    counter: dict = {}
    try:
        descendants = window.descendants()
    except Exception as e:
        raise RuntimeError(f"Lecture de l'arbre UI impossible (fenêtre élevée/admin ?) : {e}")
    for ctrl in descendants:
        try:
            ctype = ctrl.element_info.control_type or ""
            if ctype not in _GUI_INTERACTIVE_TYPES:
                continue
            name_raw = (ctrl.window_text() or "").strip()
            auto_id = ctrl.element_info.automation_id or ""
            # v2.150 — Windows masque déjà le contenu des champs mot de passe au niveau UI
            # Automation lui-même (vérifié en réel : IsPassword=True → window_text()/get_value()
            # renvoient tous deux "" pour un WinForms PasswordChar) — rien à faire pour empêcher
            # une fuite ici. On étiquette juste explicitement le champ pour que ni le LLM ni
            # l'utilisateur ne confondent un name vide "masqué par l'OS" avec un champ inconnu.
            is_password = False
            try:
                is_password = bool(ctrl.element_info.element.CurrentIsPassword)
            except Exception:
                pass
            if not name_raw and not auto_id and not is_password:
                continue
            enabled = ctrl.is_enabled()
            visible = ctrl.is_visible()
        except Exception:
            continue
        # Pour Edit/Document, le contenu n'est jamais une clé de matching (cf. note ci-dessus).
        match_key_name = "" if ctype in _GUI_CONTENT_TYPES else name_raw
        display_name = "(champ mot de passe — masqué par Windows)" if is_password else \
            ((name_raw[:100] + "…") if len(name_raw) > 100 else name_raw)
        key = (ctype, match_key_name)
        idx = counter.get(key, 0)
        counter[key] = idx + 1
        elements.append({
            "control_type": ctype, "name": display_name, "automation_id": auto_id,
            "match_index": idx, "enabled": enabled, "visible": visible, "is_password": is_password,
        })
        if len(elements) >= max_elements:
            break
    return {"success": True, "window_title": title, "count": len(elements), "elements": elements}


def _gui_resolve_sync(search: str, control_type: str, name: str, automation_id: str, match_index: int):
    window, title = _gui_get_window_sync(search)
    if automation_id:
        matches = window.descendants(auto_id=automation_id, control_type=control_type) if control_type \
            else window.descendants(auto_id=automation_id)
    elif control_type in _GUI_CONTENT_TYPES:
        # Contenu non fiable comme clé (cf. _GUI_CONTENT_TYPES) — matching par position uniquement.
        matches = window.descendants(control_type=control_type)
    else:
        matches = [c for c in window.descendants(control_type=control_type)
                   if (c.window_text() or "").strip() == name]
    if not matches:
        raise RuntimeError(
            "Élément introuvable — l'interface a changé depuis la dernière lecture "
            "(refais un pc_gui_read pour re-vérifier l'état actuel)."
        )
    idx = min(max(match_index, 0), len(matches) - 1)
    return window, title, matches[idx]


async def execute_pc_gui_read(args: dict) -> dict:
    search = (args.get("window") or "").strip()
    max_elements = max(1, min(int(args.get("max_elements", 40)), 100))
    try:
        return await asyncio.to_thread(_gui_read_sync, search, max_elements)
    except Exception as e:
        return {"error": str(e)}


async def execute_pc_gui_click(args: dict) -> dict:
    search = (args.get("window") or "").strip()
    control_type = (args.get("control_type") or "").strip()
    name = (args.get("name") or "").strip()
    automation_id = (args.get("automation_id") or "").strip()
    match_index = int(args.get("match_index", 0))
    if not control_type and not automation_id:
        return {"error": "Paramètre 'control_type' ou 'automation_id' requis (issus d'un pc_gui_read récent)."}
    if not args.get("confirmed"):
        target_desc = automation_id or f"{control_type} « {name} »"
        return {"requiresConfirmation": True,
                "message": f"Cliquer sur l'élément {target_desc} dans la fenêtre "
                            f"« {search or '(premier plan)'} » ?"}

    def _click():
        window, title, ctrl = _gui_resolve_sync(search, control_type, name, automation_id, match_index)
        if not ctrl.is_enabled():
            raise RuntimeError("Élément désactivé — impossible de cliquer.")
        ctrl.click_input()
        return title

    try:
        title = await asyncio.to_thread(_click)
        return {"success": True, "message": f"Clic effectué sur « {name or automation_id} » dans « {title} »."}
    except Exception as e:
        return {"error": str(e)}


async def execute_pc_gui_type(args: dict) -> dict:
    search = (args.get("window") or "").strip()
    control_type = (args.get("control_type") or "").strip()
    name = (args.get("name") or "").strip()
    automation_id = (args.get("automation_id") or "").strip()
    match_index = int(args.get("match_index", 0))
    text = args.get("text", "")
    if not control_type and not automation_id:
        return {"error": "Paramètre 'control_type' ou 'automation_id' requis (issus d'un pc_gui_read récent)."}
    if not text:
        return {"error": "Paramètre 'text' requis."}
    if not args.get("confirmed"):
        target_desc = automation_id or f"{control_type} « {name} »"
        preview = text[:80] + ("…" if len(text) > 80 else "")
        return {"requiresConfirmation": True,
                "message": f"Écrire « {preview} » dans l'élément {target_desc} de la fenêtre "
                            f"« {search or '(premier plan)'} » ?"}

    def _type():
        window, title, ctrl = _gui_resolve_sync(search, control_type, name, automation_id, match_index)
        if not ctrl.is_enabled():
            raise RuntimeError("Élément désactivé — impossible d'y écrire.")
        ctrl.set_focus()
        try:
            ctrl.set_edit_text(text)
        except Exception:
            ctrl.type_keys(text, with_spaces=True)
        return title

    try:
        title = await asyncio.to_thread(_type)
        return {"success": True, "message": f"Texte écrit dans « {name or automation_id} » de « {title} »."}
    except Exception as e:
        return {"error": str(e)}


async def execute_pc_notify(args: dict) -> dict:
    title = args.get("title", "SecretaryAI")
    message = args.get("message", "")
    try:
        from plyer import notification
        notification.notify(
            title=title,
            message=message,
            app_name="Marvin",
            timeout=10,
        )
        return {"success": True, "message": "Notification envoyée"}
    except Exception:
        # Fallback via PowerShell toast (use -EncodedCommand to avoid injection)
        try:
            import base64
            # Escape backtick then double-quote for PS double-quoted strings
            safe_title   = title.replace("`", "``").replace('"', '`"')
            safe_message = message.replace("`", "``").replace('"', '`"')
            ps = (
                f'[Windows.UI.Notifications.ToastNotificationManager,'
                f'Windows.UI.Notifications,ContentType=WindowsRuntime] | Out-Null;'
                f'$xml = [Windows.UI.Notifications.ToastNotificationManager]::GetTemplateContent('
                f'[Windows.UI.Notifications.ToastTemplateType]::ToastText02);'
                f'$xml.GetElementsByTagName("text")[0].AppendChild($xml.CreateTextNode("{safe_title}")) | Out-Null;'
                f'$xml.GetElementsByTagName("text")[1].AppendChild($xml.CreateTextNode("{safe_message}")) | Out-Null;'
                f'$toast = [Windows.UI.Notifications.ToastNotification]::new($xml);'
                f'[Windows.UI.Notifications.ToastNotificationManager]::CreateToastNotifier("SecretaryAI").Show($toast);'
            )
            encoded = base64.b64encode(ps.encode("utf-16-le")).decode("ascii")
            await asyncio.to_thread(subprocess.run, ["powershell", "-NoProfile", "-EncodedCommand", encoded], timeout=5, capture_output=True)
            return {"success": True, "message": "Notification envoyée"}
        except Exception as e2:
            return {"error": str(e2)}


async def execute_pc_pull_ollama_model(args: dict) -> dict:
    model = args.get("model", "llama3.2:3b")
    try:
        import httpx
        async with httpx.AsyncClient(timeout=600.0) as client:
            resp = await client.post(
                f"{OLLAMA_URL}/api/pull",
                json={"name": model},
                timeout=600.0,
            )
            resp.raise_for_status()
        return {"success": True, "message": f"Modèle téléchargé : {model}"}
    except Exception as e:
        return {"error": str(e)}


async def execute_pc_clipboard_get(args: dict) -> dict:
    # 1. win32clipboard (rapide, fiable) — vérifie le format AVANT de lire pour
    #    éviter l'exception sur presse-papiers vide / non-texte, et ferme toujours.
    try:
        import win32clipboard
        win32clipboard.OpenClipboard()
        try:
            if win32clipboard.IsClipboardFormatAvailable(win32clipboard.CF_UNICODETEXT):
                text = win32clipboard.GetClipboardData(win32clipboard.CF_UNICODETEXT) or ""
            elif win32clipboard.IsClipboardFormatAvailable(win32clipboard.CF_TEXT):
                raw = win32clipboard.GetClipboardData(win32clipboard.CF_TEXT) or b""
                text = raw.decode("utf-8", "replace") if isinstance(raw, bytes) else str(raw)
            else:
                # Détecte les contenus non-texte (image, fichiers) pour informer l'utilisateur
                has_img = win32clipboard.IsClipboardFormatAvailable(win32clipboard.CF_DIB)
                has_files = win32clipboard.IsClipboardFormatAvailable(win32clipboard.CF_HDROP)
                kind = "image" if has_img else "fichier(s)" if has_files else "vide"
                return {"success": True, "text": "", "empty": True, "content_type": kind,
                        "message": f"Le presse-papiers ne contient pas de texte ({kind})."}
        finally:
            win32clipboard.CloseClipboard()
        return {"success": True, "text": text, "length": len(text), "empty": text == ""}
    except Exception:
        pass
    # 2. Fallback PowerShell (décodage binaire sûr pour éviter le crash cp1252)
    try:
        result = await asyncio.to_thread(
            subprocess.run,
            ["powershell", "-NoProfile", "-Command", "Get-Clipboard -Raw"],
            capture_output=True, timeout=8,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        )
        text = (result.stdout or b"").decode("utf-8", "replace").rstrip("\r\n")
        return {"success": True, "text": text, "length": len(text), "empty": text == ""}
    except Exception as e:
        return {"error": str(e)}


async def execute_pc_clipboard_set(args: dict) -> dict:
    text = args.get("text", "")
    try:
        import win32clipboard
        win32clipboard.OpenClipboard()
        win32clipboard.EmptyClipboard()
        win32clipboard.SetClipboardData(win32clipboard.CF_UNICODETEXT, text)
        win32clipboard.CloseClipboard()
        return {"success": True, "message": "Texte copié dans le presse-papiers"}
    except Exception:
        try:
            import base64
            # Use -EncodedCommand to avoid shell injection with special characters/quotes
            ps_script = f"Set-Clipboard -Value '{text.replace(chr(39), chr(39)+chr(39))}'"
            encoded = base64.b64encode(ps_script.encode('utf-16-le')).decode('ascii')
            await asyncio.to_thread(
                subprocess.run,
                f'powershell -NoProfile -EncodedCommand {encoded}', shell=True, timeout=5
            )
            return {"success": True, "message": "Texte copié dans le presse-papiers"}
        except Exception as e:
            return {"error": str(e)}


async def execute_pc_process_list(args: dict) -> dict:
    sort_by = args.get("sort_by", "memory")  # cpu | memory | name
    try:
        procs = []
        for p in psutil.process_iter(["pid", "name", "cpu_percent", "memory_info", "status"]):
            try:
                info = p.info
                procs.append({
                    "pid": info["pid"],
                    "name": info["name"],
                    "cpu_percent": info["cpu_percent"] or 0.0,
                    "memory_mb": round(info["memory_info"].rss / 1024**2, 1) if info["memory_info"] else 0,
                    "status": info["status"],
                })
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                pass
        if sort_by == "cpu":
            procs.sort(key=lambda x: x["cpu_percent"], reverse=True)
        elif sort_by == "name":
            procs.sort(key=lambda x: x["name"].lower())
        else:  # memory (défaut)
            procs.sort(key=lambda x: x["memory_mb"], reverse=True)
        return {"success": True, "count": len(procs), "processes": procs[:50]}
    except Exception as e:
        return {"error": str(e)}


async def execute_pc_process_kill(args: dict) -> dict:
    if not args.get("confirmed"):
        pid = args.get("pid")
        name = args.get("name", "")
        return {"requiresConfirmation": True, "message": f"Arrêter le processus {name or ''} (PID {pid}) ?"}
    pid = args.get("pid")
    name = args.get("name", "")
    try:
        if pid:
            proc = psutil.Process(int(pid))
            proc.terminate()
            return {"success": True, "message": f"Processus {pid} terminé"}
        elif name:
            killed = 0
            for p in psutil.process_iter(["pid", "name"]):
                if name.lower() in p.info["name"].lower():
                    p.terminate()
                    killed += 1
            return {"success": True, "message": f"{killed} processus '{name}' terminés"}
        return {"error": "PID ou nom de processus requis"}
    except Exception as e:
        return {"error": str(e)}


# ══════════════════════════════════════════════════════════════════════════════
# SECTION 3 — Tâches
# ══════════════════════════════════════════════════════════════════════════════

def _parse_tags(raw) -> list[str]:
    """Normalise les tags : str 'a, b, c' → ['a','b','c'] ou list → list."""
    if isinstance(raw, list):
        return [str(t).strip() for t in raw if str(t).strip()]
    if isinstance(raw, str) and raw.strip():
        return [t.strip() for t in raw.split(",") if t.strip()]
    return []


async def execute_task_create(args: dict) -> dict:
    try:
        task = db.create_task(
            title=args["title"],
            description=args.get("description", ""),
            priority=args.get("priority", "medium"),
            due_date=args.get("due_date", None),
            tags=_parse_tags(args.get("tags", [])),
        )
        return {"success": True, "message": f"Tâche créée : « {task['title']} »", "task": task}
    except Exception as e:
        return {"error": str(e)}


async def execute_task_list(args: dict) -> dict:
    try:
        status = args.get("status") or None
        # L'UI envoie "all" pour "toutes les tâches" → pas de filtre
        if status == "all":
            status = None
        tasks = db.list_tasks(
            status=status,
            priority=args.get("priority"),
        )
        return {"success": True, "count": len(tasks), "tasks": tasks}
    except Exception as e:
        return {"error": str(e)}


async def execute_task_update(args: dict) -> dict:
    tid = args.get("id", "")
    if not tid:
        return {"error": "ID de tâche requis"}
    # Normalize status: the LLM sometimes says 'completed' — map to 'done'
    _STATUS_ALIASES = {
        "completed": "done", "terminé": "done", "termine": "done", "fini": "done",
        "wip": "in_progress", "en cours": "in_progress", "started": "in_progress",
        "todo": "pending", "à faire": "pending", "a faire": "pending",
        "annulé": "cancelled", "annule": "cancelled", "canceled": "cancelled",
    }
    if "status" in args:
        args = dict(args)
        args["status"] = _STATUS_ALIASES.get(args["status"].lower().strip(), args["status"])
    try:
        task = db.update_task(tid, args)
        if not task:
            return {"error": f"Tâche introuvable : {tid}"}
        return {"success": True, "message": "Tâche mise à jour", "task": task}
    except Exception as e:
        return {"error": str(e)}


async def execute_task_delete(args: dict) -> dict:
    tid = args.get("id", "")
    if not tid:
        return {"error": "ID de tâche requis"}
    # Charger le titre pour un message de confirmation lisible
    if not args.get("confirmed"):
        try:
            task_preview = db.get_task(tid)
            label = f"« {task_preview['title']} »" if task_preview else f"ID {tid}"
        except Exception:
            label = f"ID {tid}"
        return {"requiresConfirmation": True, "message": f"Supprimer définitivement la tâche {label} ?"}
    try:
        task = db.get_task(tid)
        if not task:
            return {"error": f"Tâche introuvable : {tid}"}
        db.delete_task(tid)
        return {"success": True, "message": f"Tâche « {task['title']} » supprimée"}
    except Exception as e:
        return {"error": str(e)}


